#define NUM_POINTS 48
#define MAX_ITER 8
#define PI 3.14159265359

float sdLine(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

float sdArrow(vec2 p, vec2 a, vec2 b) {
    float line = sdLine(p, a, b);

    vec2 dir = normalize(b - a);
    vec2 normal = vec2(-dir.y, dir.x);
    float arrowSize = 0.01;
    vec2 arrowTip = b - dir * arrowSize;

    float leftWing = sdLine(p, b, arrowTip + normal * arrowSize);
    float rightWing = sdLine(p, b, arrowTip - normal * arrowSize);

    return min(line, min(leftWing, rightWing));
}

float S(float v) {
    vec2 r = vec2(iResolution.x, iResolution.y);
    float aa_width = 1.5/r.y;
    return smoothstep(aa_width, 0.0, v);
}

float map(in vec2[NUM_POINTS] v, in vec2 p) {
    float d = 9999.0;

    for(int i=0; i<NUM_POINTS; i++) {
        vec2 w = p - v[i];
        d = min(d, dot(w, w));
    }


    return sqrt(d);
}

vec2 findNearest(vec2 query, vec2[NUM_POINTS] points) {
    float minDist = 1000.0;
    vec2 nearest = points[0];

    for(int i = 0; i < NUM_POINTS; i++) {
        vec2 p = points[i];
        float dist = length(query - p);
        if(dist < minDist) {
            minDist = dist;
            nearest = p;
        }
    }
    return nearest;
}

float computeRadius(vec2 p, vec2 n, vec2 q) {
    vec2 v = q - p;
    float d = length(v);

    // Early exit for very close points
    if(d < 1e-6) return 0.1;

    float cos_theta = dot(n, v) / d;

    // Handle near-perpendicular case
    if(abs(cos_theta) < 1e-6) return 0.1;

    float r = d / (2.0 * cos_theta);

    // Clamp radius to reasonable bounds
    return clamp(r, 0.01, 1.0);
}

vec2 computeNextBallCenter(vec2 p, vec2 qnext, vec2 n) {
    // Compute radius first
    float rnext = computeRadius(p, n, qnext);

    // Center is simply p + n * r
    return p + n * rnext;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Color palette
    vec3 COLOR_BACKGROUND = vec3(0.8);           // Dark gray background
    vec3 COLOR_POLYGON = vec3(0.5);              // Light gray polygon
    vec3 COLOR_BALL_BASE = vec3(0.9);            // Base color for balls
    vec3 COLOR_BALL_HIGHLIGHT = vec3(0.1);       // Amount to add for ball highlights
    vec3 COLOR_CENTER_POINT = vec3(1.0);         // White center points
    vec3 COLOR_ORANGE = vec3(1.0, 0.5, 0.0);     // Orange for special elements
    vec3 COLOR_LINE = vec3(0.666);                // Lines in orange
    vec3 COLOR_ARROW = COLOR_ORANGE;             // Normal vector arrow
    vec3 COLOR_START_POINT = COLOR_ORANGE;       // Starting point
    vec3 COLOR_QNEXT = COLOR_ORANGE;             // Nearest point color
    float SIZE = 0.01;

    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec3 col = COLOR_BACKGROUND;

    vec2[NUM_POINTS] vertices;
    for(int i = 0; i < NUM_POINTS; i++) {
        float angle = float(i) * 2.0 * PI / float(NUM_POINTS);
        vertices[i] = vec2(
            cos(angle) * 0.3 - sin(angle * 0.5) * 0.5 + 0.5 * 0.5,
            sin(angle) * 0.25 + cos(angle * 7.0 - 0.5 - angle * angle * 0.2) * 0.04
        );
    }

    float d = map(vertices, uv);
    col = mix(COLOR_POLYGON, col, 1.0 - S(abs(d) - SIZE * 0.5));

    // Algorithm parameters
    vec2 p0 = vertices[NUM_POINTS / 2 + 3];
    vec2 p = vertices[NUM_POINTS / 2 + 2];
    vec2 e = normalize(p0 - p); 
    vec2 n = vec2(-e.y, e.x);
    float r = 0.4;
    vec2 c = p + n * r;

    float time = mod(iTime * 1.25, float(MAX_ITER));
    int currentStep = int(floor(time));
    float stepProgress =  fract(time);

    vec2[MAX_ITER] centers;
    float[MAX_ITER] radii;
    vec2[MAX_ITER] qnexts;
    int actualIters = 0;

    // Run algorithm
    for(int iter = 0; iter < MAX_ITER; iter++) {
        centers[iter] = c;
        radii[iter] = r;

        vec2 qnext = findNearest(c, vertices);
        qnexts[iter] = qnext;

        // Skip if nearest point is p itself
        if(length(qnext - p) < 1e-6) {
            qnext = vertices[0]; // Pick another point
            for(int i = 0; i < NUM_POINTS; i++) {
                if(length(vertices[i] - p) > 1e-6) {
                    qnext = vertices[i];
                    break;
                }
            }
        }

        vec2 cnext = computeNextBallCenter(p, qnext, n);
        float rnext = length(cnext - p);

        // Better convergence check
        if(abs(rnext - r) < 1e-6 || rnext < 0.01 || rnext > 0.4) {
            actualIters = iter + 1;
            break;
        }

        c = cnext;
        r = rnext;
    }

    // Visualization
    for(int i = 0; i < actualIters ; i++) {
        if(i > currentStep && currentStep != actualIters - 1) break;


        float alpha = (i == currentStep) ? smoothstep(0.0, 0.3, stepProgress) : 1.0;
        float highlight = (i == currentStep) ? 
            (0.5 + 0.5 * sin(stepProgress * PI * 4.0)) : 0.0;


        // Draw connection lines
        if(i == currentStep) {
            float lineDist = sdLine(uv, centers[i], qnexts[i]);
            col = mix(col, COLOR_LINE, alpha * S(lineDist - SIZE * 0.1));
        }

        // Draw points
        float centerDot = length(uv - centers[i]);
        float qnextDot = length(uv - qnexts[i]);

        col = mix(col, COLOR_QNEXT, alpha * S(qnextDot - SIZE * 0.5));
        col = mix(col, COLOR_CENTER_POINT, alpha * S(centerDot - SIZE));

        // Draw balls
        float ballDist = abs(length(uv - centers[i]) - radii[i]);
        vec3 ballColor = COLOR_BALL_BASE + COLOR_BALL_HIGHLIGHT * highlight;

        col = mix(col, ballColor, alpha * S(ballDist - SIZE * 0.1));
         col = mix(col, COLOR_BALL_BASE, (i == currentStep || (i == actualIters - 1 && currentStep >= actualIters - 1)) ? S(length(uv - centers[i]) - radii[i] - SIZE * 0.1) * 0.5 : 0.0);  
       }

    // Draw start point
    float pDot = length(uv - p);
    col = mix(col, COLOR_START_POINT, S(pDot - SIZE));

    // Draw normal vector arrow
    float arrowDist = sdArrow(uv, p, p + n * 0.075);
    col = mix(col, COLOR_ARROW, S(arrowDist - SIZE * 0.1));

    fragColor = vec4(col, 1.0);
}
